modals.attributes:
busy={loading}
          cancelLabel="Отмена"
          className="checklist-item-editor-modal"
          confirmLabel="Сохранить"
          dirty={JSON.stringify(templateBuilder.editorDraft) !== JSON.stringify(templateBuilder.editorInitialDraft)}
          errorText={errorText}
          onCancel={() => {
            setTemplateBuilder({ ...templateBuilder, editorIndex: null, editorDraft: null, editorInitialDraft: null });
            setErrorText(null);
          }}
          onSubmit={() => commitBuilderEditor()}
          title={templateBuilder.editorIndex !== null && templateBuilder.editorIndex >= 0 ? 'Редактирование пункта' : 'Новый пункт'}

busy={loading}
          cancelLabel="Отмена"
          confirmLabel={
            modal.mode === 'start'
              ? 'Взять в работу'
              : modal.mode === 'close'
                ? isPeriodicChecklistRun(modal.run) ? 'Завершить чек-лист полностью' : 'Завершить чек-лист'
                : modal.mode === 'resume'
                  ? 'Возобновить'
                  : modal.mode === 'archive-row' || modal.mode === 'archive-template'
                    ? 'Подтвердить'
                    : 'Сохранить'
          }
          errorText={errorText}
          fields={
            modal.mode === 'pause'
              ? [{ name: 'reason', label: 'Причина паузы', type: 'textarea', required: true }]
              : modal.mode === 'close'
                ? [{
                    name: 'comment',
                    label: isPeriodicChecklistRun(modal.run) ? 'Причина досрочного завершения' : 'Причина завершения',
                    type: 'textarea',
                    required: true,
                  }]
                : modal.mode === 'edit-template'
                  ? templateFields(modal.template)
                  : modal.mode === 'create-template'
                    ? templateFields()
                    : []
          }
          onCancel={() => {
            setFilesByRow({});
            setStandaloneRowDraft(null);
            setModal(null);
          }}
          onSubmit={submitModal}
          title={modal.title}

title="Полностью завершить запись"
          description="После подтверждения запись будет скрыта из активного списка и останется в архиве."
          busy={busy}
          errorText={errorText}
          confirmLabel="Подтвердить"
          onCancel={() => setModal(null)}
          onSubmit={async () => {
            if (await postAction(activeId, 'full-complete')) {
              setModal(null);
              setActiveId(null);
            }
          }}

busy={loading}
          confirmLabel={modal.mode === 'restore' ? 'Восстановить' : 'Сохранить'}
          errorText={errorText}
          fields={modalFields()}
          onCancel={() => { setModal(null); setModalOperationId(''); }}
          onSubmit={(values) => runAction(values)}
          title={modal.title}

busy={loading}
          dirty={Boolean(lineId)}
          fields={skillFields}
          title="Добавить навык"
          confirmLabel="Добавить"
          onCancel={() => { setModal(null); setLineId(''); }}
          onSubmit={createSkill}

busy={loading}
          description="Автоматическое начисление остаётся основным. Здесь руководитель может исправить подтверждённую ошибку учёта."
          fields={[
            { name: 'experienceCount', label: 'Фактический опыт', type: 'number', required: true, defaultValue: selectedSkill.experienceCount },
            { name: 'isActive', label: 'Навык активен', type: 'checkbox', defaultValue: true },
          ]}
          title="Изменить навык"
          confirmLabel="Сохранить"
          onCancel={() => { setModal(null); setSelectedSkill(null); }}
          onSubmit={updateSkill}

busy={loading}
          fields={[
            { name: 'text', label: 'Заметка', type: 'textarea', required: true },
            {
              name: 'visibility',
              label: 'Видимость',
              type: 'select',
              defaultValue: 'MANAGEMENT',
              options: [{ label: 'Руководство', value: 'MANAGEMENT' }, { label: 'Только администратор', value: 'ADMIN' }],
            },
          ]}
          title="Заметка руководства"
          confirmLabel="Сохранить"
          onCancel={() => setModal(null)}
          onSubmit={createNote}

busy={loading}
          fields={[{ name: 'text', label: 'Заметка', type: 'textarea', required: true, defaultValue: selectedNote.text }]}
          title="Изменить заметку"
          confirmLabel="Сохранить"
          onCancel={() => setModal(null)}
          onSubmit={updateNote}

busy={loading}
          title="Удалить заметку"
          description="Заметка будет скрыта, физическое удаление не выполняется."
          confirmLabel="Удалить"
          onCancel={() => setModal(null)}
          onSubmit={deleteNote}

busy={loading}
          title="Сбросить пароль"
          description={`Действующие сессии сотрудника «${profile.displayName}» завершатся. При следующем входе он задаст новый пароль без старого.`}
          fields={[{ name: 'reason', label: 'Причина', type: 'textarea', required: true }]}
          confirmLabel="Сбросить пароль"
          onCancel={() => setModal(null)}
          onSubmit={resetPassword}

busy={loading}
          errorText={errorText}
          fields={[
            { name: 'title', label: 'Заголовок' },
            { name: 'logDate', label: 'Дата', type: 'date', defaultValue: todayKey(), required: true },
            { name: 'shiftLabel', label: 'Смена', type: 'select', options: [{ label: 'День', value: 'День' }, { label: 'Ночь', value: 'Ночь' }], defaultValue: 'День', required: true },
            { name: 'text', label: 'Комментарий к смене', type: 'textarea', required: true },
            ...(currentUser?.isAdmin ? [{ name: 'departmentId', label: 'Отдел', type: 'select' as const, options: departmentOptions, defaultValue: currentUser.departmentId ?? '', required: true }] : []),
            ...(canImportant ? [{ name: 'isImportant', label: 'Важная запись', type: 'checkbox' as const }] : []),
          ]}
          onCancel={() => setModal(null)}
          onSubmit={submitModal}
          title="Новая запись"

title={pendingAction.mode === 'start' || pendingAction.status === 'WORK' ? 'Вернуть в работу' : `Изменить статус: ${statusMeta[pendingAction.status].label}`}
          description={`${pendingAction.line.name}. ${statusDescription(pendingAction.mode === 'start' ? 'WORK' : pendingAction.status)}`}
          fields={[
            {
              name: 'effectiveMode',
              label: 'Время события',
              type: 'select',
              defaultValue: 'NOW',
              required: true,
              options: [
                { label: 'Сейчас', value: 'NOW' },
                { label: 'Указать фактическое время', value: 'CUSTOM' },
              ],
            },
            {
              name: 'effectiveAt',
              label: 'Фактическое время',
              type: 'datetime-local',
              defaultValue: factoryDateTimeInput(serverNowIso),
            },
            ...(pendingAction.mode !== 'start' && (pendingAction.status === 'PAUSE' || pendingAction.status === 'STOP') ? [{
              name: 'downtimeReason',
              label: 'Причина простоя',
              type: 'select' as const,
              required: true,
              defaultValue: downtimeReasons[0]?.value ?? '',
              options: downtimeReasons,
            }] : []),
            {
              name: 'comment',
              label: 'Комментарий',
              type: 'textarea',
              required: pendingAction.mode !== 'start' && (pendingAction.status === 'PAUSE' || pendingAction.status === 'STOP'),
            },
          ]}
          confirmLabel="Подтвердить"
          busy={actionBusy}
          errorText={errorText}
          onCancel={() => setPendingAction(null)}
          onSubmit={confirmAction}

title="Создать некондицию"
          fields={[
            { name: 'name', label: 'Наименование', placeholder: 'Можно оставить пустым' },
            { name: 'quantity', label: 'Количество', type: 'number', required: true },
            { name: 'unit', label: 'Единица', type: 'select', required: true, defaultValue: 'штуки', options: unitOptions },
          ]}
          busy={busy}
          errorText={errorText}
          confirmLabel="Создать"
          onCancel={() => setModal(null)}
          onSubmit={async (values) => {
            setBusy(true);
            setErrorText(null);
            try {
              await apiClient.post('/stock', { name: String(values.name ?? ''), quantity: Number(values.quantity), unit: String(values.unit ?? 'штуки') });
              setModal(null);
              await load();
            } catch (error) {
              setErrorText(error instanceof Error ? error.message : 'Не удалось создать некондицию.');
            } finally {
              setBusy(false);
            }
          }}

title="Редактировать некондицию"
          fields={[
            { name: 'name', label: 'Наименование', defaultValue: active.name ?? active.productName ?? '' },
            { name: 'quantity', label: 'Количество', type: 'number', required: true, defaultValue: active.quantity },
            { name: 'unit', label: 'Единица', type: 'select', required: true, defaultValue: defectUnit(active), options: unitOptions },
          ]}
          busy={busy}
          errorText={errorText}
          confirmLabel="Сохранить"
          onCancel={() => setModal(null)}
          onSubmit={async (values) => {
            setBusy(true);
            setErrorText(null);
            try {
              await apiClient.patch(`/stock/${active.id}`, { name: String(values.name ?? ''), quantity: Number(values.quantity), unit: String(values.unit ?? 'штуки') });
              setModal(null);
              setActiveId(null);
              await load();
            } catch (error) {
              setErrorText(error instanceof Error ? error.message : 'Не удалось обновить некондицию.');
            } finally {
              setBusy(false);
            }
          }}

title="Выдать некондицию"
          fields={[{ name: 'comment', label: 'Комментарий выдачи', type: 'textarea', required: true }]}
          busy={busy}
          errorText={errorText}
          confirmLabel="Выдать"
          onCancel={() => setModal(null)}
          onSubmit={async (values) => {
            setBusy(true);
            setErrorText(null);
            try {
              await apiClient.post(`/stock/${activeId}/issue`, { comment: String(values.comment) });
              setModal(null);
              setActiveId(null);
              await load();
            } catch (error) {
              setErrorText(error instanceof Error ? error.message : 'Не удалось выдать некондицию.');
            } finally {
              setBusy(false);
            }
          }}

busy={busy}
          errorText={errorText}
          title="Создать заявку"
          fields={[
            { name: 'description', label: 'Описание', type: 'textarea', required: true },
            { name: 'type', label: 'Тип', type: 'select', required: true, defaultValue: 'URGENT', options: [{ label: 'Срочная', value: 'URGENT' }, { label: 'Долгая', value: 'LONG' }] },
            { name: 'lineId', label: 'Линия', type: 'select', options: lines.map((line) => ({ label: line.name, value: line.id })) },
            { name: 'departmentId', label: 'Служба / отдел', type: 'select', options: departments.map((department) => ({ label: department.name, value: department.id })) },
            { name: 'assigneeUserId', label: 'Конкретный исполнитель', type: 'select', options: candidates.map((candidate) => ({ label: `${candidate.displayName} · ${candidate.role === 'OTHER' && candidate.departmentName ? candidate.departmentName : roleLabel(candidate.role)}`, value: candidate.userId })) },
            { name: 'deadlineAt', label: 'Дедлайн для долгой заявки', type: 'datetime-local', defaultValue: buildDeadline(settings?.longTaskDefaultDeadlineHours ?? 48) },
          ]}
          onCancel={closeTaskModal}
          onSubmit={async (values) => {
            if (actionInFlightRef.current) return;
            actionInFlightRef.current = true;
            setBusy(true);
            setErrorText(null);
            try {
            const type = String(values.type || 'URGENT').toUpperCase() === 'LONG' ? 'LONG' : 'URGENT';
            const task = await apiClient.post<Task>('/tasks', {
              type,
              description: String(values.description),
              lineId: values.lineId ? String(values.lineId) : null,
              departmentRecipientIds: values.departmentId ? [String(values.departmentId)] : [],
              assigneeUserIds: values.assigneeUserId ? [String(values.assigneeUserId)] : [],
              deadlineAt: type === 'LONG' ? new Date(String(values.deadlineAt || buildDeadline(settings?.longTaskDefaultDeadlineHours ?? 48))).toISOString() : null,
              operationId: modalOperationId || createOperationId('task-create'),
            });
            if (files.length) await uploadFiles('TASK', task.id, files);
            setFiles([]);
            closeTaskModal();
            await load();
            await loadArchive();
            } catch (error) {
              setErrorText(errorMessage(error, 'Не удалось создать заявку'));
            } finally {
              actionInFlightRef.current = false;
              setBusy(false);
            }
          }}

busy={busy}
          errorText={errorText}
          title="Передать заявку"
          fields={[
            { name: 'comment', label: 'Комментарий', type: 'textarea', required: true },
            { name: 'departmentId', label: 'Новая служба / отдел', type: 'select', options: departments.map((department) => ({ label: department.name, value: department.id })) },
            { name: 'assigneeUserId', label: 'Новый конкретный исполнитель', type: 'select', options: candidates.map((candidate) => ({ label: `${candidate.displayName} · ${candidate.role === 'OTHER' && candidate.departmentName ? candidate.departmentName : roleLabel(candidate.role)}`, value: candidate.userId })) },
          ]}
          onCancel={closeTaskModal}
          onSubmit={async (values) => {
            if (actionInFlightRef.current) return;
            actionInFlightRef.current = true;
            setBusy(true);
            setErrorText(null);
            try {
            await apiClient.post(`/tasks/${selectedTask.id}/redirect`, {
              comment: String(values.comment),
              newDepartmentRecipientIds: values.departmentId ? [String(values.departmentId)] : [],
              newAssigneeUserIds: values.assigneeUserId ? [String(values.assigneeUserId)] : [],
              operationId: modalOperationId || createOperationId('task-redirect'),
            });
            closeTaskModal();
            await load();
            await loadArchive();
            await openDetail(selectedTask);
            } catch (error) {
              setErrorText(errorMessage(error, 'Не удалось передать заявку'));
            } finally {
              actionInFlightRef.current = false;
              setBusy(false);
            }
          }}

busy={busy}
          errorText={errorText}
          title="Завершить заявку"
          fields={[{ name: 'comment', label: selectedTask.overdue ? 'Комментарий к закрытию просрочки' : 'Комментарий', type: 'textarea', required: Boolean(selectedTask.overdue && selectedTask.type === 'LONG') }]}
          onCancel={closeTaskModal}
          onSubmit={async (values) => {
            if (actionInFlightRef.current) return;
            actionInFlightRef.current = true;
            setBusy(true);
            setErrorText(null);
            try {
            await apiClient.post(`/tasks/${selectedTask.id}/complete`, {
              operationId: modalOperationId || createOperationId('task-done'),
              comment: String(values.comment || ''),
            });
            closeTaskModal();
            setSelectedTask(null);
            await load();
            await loadArchive();
            } catch (error) {
              setErrorText(errorMessage(error, 'Не удалось завершить заявку'));
            } finally {
              actionInFlightRef.current = false;
              setBusy(false);
            }
          }}

busy={loading}
            errorText={errorText}
            title="Фото или комментарий"
            fields={[{ name: 'message', label: 'Комментарий', type: 'textarea', required: true }]}
            onCancel={resetModal}
            onSubmit={async (values) => {
              setLoading(true);
              setErrorText(null);
              try {
                const message = await apiClient.post<{ id: string }>(`/wash/${current.id}/message`, { message: String(values.message), operationId: createOperationId('wash-message') });
                await uploadAttachments('WASH_MESSAGE', message.id, files);
                resetModal();
                await reloadDetail(current.id);
              } catch (error) {
                setErrorText(error instanceof Error ? error.message : 'Не удалось сохранить комментарий к мойке.');
              } finally {
                setLoading(false);
              }
            }}

title="Проблема мойки"
            fields={[
              { name: 'title', label: 'Коротко что не так', required: true },
              { name: 'description', label: 'Описание', type: 'textarea', required: true },
            ]}
            onCancel={resetModal}
            onSubmit={async (values) => {
              const issue = await apiClient.post<{ id: string }>(`/wash/${current.id}/issues`, {
                title: String(values.title),
                description: String(values.description),
                operationId: createOperationId('wash-issue'),
              });
              await uploadAttachments('WASH_ISSUE', issue.id, files);
              resetModal();
              await reloadDetail(current.id);
            }}

title="Задание по мойке"
            fields={[
              { name: 'title', label: 'Что проверить или домыть', required: true },
              { name: 'description', label: 'Комментарий', type: 'textarea' },
              { name: 'type', label: 'Тип', type: 'select', options: [{ value: 'CONTROL', label: 'Контроль' }, { value: 'MINI_TASK', label: 'Мини-задача' }], defaultValue: 'CONTROL' },
              { name: 'requiresPhoto', label: 'Требовать фото при выполнении', type: 'checkbox' },
            ]}
            onCancel={resetModal}
            onSubmit={async (values) => {
              const item = await apiClient.post<{ id: string }>(`/wash/${current.id}/control-items`, {
                title: String(values.title),
                description: String(values.description || ''),
                type: String(values.type || 'CONTROL') as 'CONTROL',
                requiresPhoto: Boolean(values.requiresPhoto),
              });
              await uploadAttachments('WASH_CONTROL_ITEM', item.id, files);
              resetModal();
              await reloadDetail(current.id);
            }}

busy={loading}
            errorText={errorText}
            title="ОКК-проверка мойки"
            fields={[
              { name: 'status', label: 'Решение', type: 'select', options: [{ value: 'APPROVED', label: 'Принято' }, { value: 'NEEDS_REWORK', label: 'Нужно домыть' }, { value: 'REJECTED', label: 'Отклонено' }], defaultValue: 'APPROVED', required: true },
              { name: 'comment', label: 'Комментарий', type: 'textarea', required: true },
            ]}
            onCancel={resetModal}
            onSubmit={async (values) => {
              setLoading(true);
              setErrorText(null);
              try {
                const review = await apiClient.post<{ id: string }>(`/wash/${current.id}/okk-review`, {
                  status: String(values.status || 'APPROVED'),
                  rating: reviewRating ? Number(reviewRating) : undefined,
                  comment: String(values.comment),
                });
                await uploadAttachments('WASH_OKK_REVIEW', review.id, files);
                resetModal();
                await reloadDetail(current.id);
              } catch (error) {
                setErrorText(error instanceof Error ? error.message : 'Не удалось сохранить проверку ОКК.');
              } finally {
                setLoading(false);
              }
            }}

title="Закрыть проблему"
            fields={[{ name: 'comment', label: 'Что сделали', type: 'textarea', required: true }]}
            onCancel={resetModal}
            onSubmit={async (values) => {
              await apiClient.patch(`/wash/issues/${selectedIssueId}/status`, { status: 'RESOLVED', comment: String(values.comment) });
              resetModal();
              await reloadDetail(current.id);
            }}

title="Выполнить задание"
            fields={[{ name: 'comment', label: 'Комментарий', type: 'textarea' }]}
            onCancel={resetModal}
            onSubmit={async (values) => {
              await uploadAttachments('WASH_CONTROL_ITEM', String(selectedControlId), files);
              await apiClient.patch(`/wash/control-items/${selectedControlId}`, { status: 'DONE', comment: String(values.comment || '') });
              resetModal();
              await reloadDetail(current.id);
            }}

busy={loading}
            className="wash-complete-modal"
            confirmLabel="Завершить мойку"
            errorText={errorText}
            title="Завершить мойку"
            description="Перед завершением проверьте открытые проблемы, задания и решение ОКК. Если правила завода не выполнены, backend вернет понятную ошибку."
            onCancel={resetModal}
            onSubmit={async () => {
              setLoading(true);
              setErrorText(null);
              try {
                await apiClient.post(`/wash/${current.id}/complete`, { operationId: createOperationId('wash-complete') });
                resetModal();
                closeDetail();
                await loadWash();
              } catch (error) {
                setErrorText(error instanceof Error ? error.message : 'Не удалось завершить мойку.');
              } finally {
                setLoading(false);
              }
            }}

busy={loading}
          errorText={errorText}
          title="Новое задание на мойку"
          fields={[
            { name: 'targetType', label: 'Что нужно помыть', type: 'select', defaultValue: 'LINE', required: true, options: [{ value: 'LINE', label: 'Линия' }, { value: 'OTHER', label: 'Другой объект' }] },
            { name: 'lineId', label: 'Линия', type: 'select', options: [{ value: '', label: 'Не выбрано' }, ...requestLineOptions] },
            { name: 'objectName', label: 'Другой объект' },
            { name: 'description', label: 'Описание работ', type: 'textarea', required: true },
            { name: 'priority', label: 'Приоритет', type: 'select', defaultValue: 'NORMAL', required: true, options: [{ value: 'LOW', label: 'Низкий' }, { value: 'NORMAL', label: 'Обычный' }, { value: 'HIGH', label: 'Высокий' }, { value: 'URGENT', label: 'Срочно' }] },
            { name: 'dueAt', label: 'Срок', type: 'datetime-local' },
            { name: 'comment', label: 'Комментарий', type: 'textarea' },
          ]}
          onCancel={resetModal}
          onSubmit={async (values) => {
            setLoading(true);
            setErrorText(null);
            try {
              const targetType = String(values.targetType || 'LINE');
              if (targetType === 'LINE' && !values.lineId) throw new Error('Выберите линию.');
              if (targetType === 'OTHER' && String(values.objectName || '').trim().length < 2) throw new Error('Укажите объект мойки.');
              const request = await apiClient.post<WashRequest>('/wash/requests', {
                targetType,
                lineId: targetType === 'LINE' ? String(values.lineId) : undefined,
                objectName: targetType === 'OTHER' ? String(values.objectName).trim() : undefined,
                description: String(values.description),
                priority: String(values.priority || 'NORMAL'),
                dueAt: values.dueAt ? new Date(String(values.dueAt)).toISOString() : undefined,
                comment: String(values.comment || '').trim() || undefined,
                operationId: createOperationId('wash-request-create'),
              });
              await uploadAttachments('WASH_CONTROL_ITEM', request.id, files);
              resetModal();
              await loadWash();
            } catch (error) {
              setErrorText(error instanceof Error ? error.message : 'Не удалось создать задание на мойку.');
            } finally {
              setLoading(false);
            }
          }}
